#[cfg(test)]
mod tests {
    use super::*;

    const SETS: [ArtSet; 2] = [ArtSet::Colour, ArtSet::Ink];
    /// (path count, packed numbers) per set, written by the generator.
    const GOLDEN_COUNTS: [(usize, usize); 2] = [(121, 8860), (388, 26583)];

    fn coords(path: &ArtPath) -> Vec<(f32, f32)> {
        path.ops()
            .flat_map(|op| match op {
                Op::Move(x, y) | Op::Line(x, y) => vec![(x, y)],
                Op::Cubic(a, b, c, d, x, y) => vec![(a, b), (c, d), (x, y)],
                Op::Close => vec![],
            })
            .collect()
    }

    #[test]
    fn every_coordinate_is_finite_and_inside_the_view_box() {
        for set in SETS {
            for id in ArtId::ALL {
                let piece = piece(set, id);
                for path in piece.paths {
                    let half = path.stroke.map_or(0.0, |s| s.width / 2.0);
                    for (x, y) in coords(path) {
                        assert!(
                            x.is_finite() && y.is_finite(),
                            "{set:?}/{id:?} has a non-finite coordinate"
                        );
                        assert!(
                            x >= -half - 0.5
                                && x <= piece.width + half + 0.5
                                && y >= -half - 0.5
                                && y <= piece.height + half + 0.5,
                            "{set:?}/{id:?} point ({x}, {y}) is outside {}x{}",
                            piece.width,
                            piece.height
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn every_path_is_painted_and_well_formed() {
        for set in SETS {
            for id in ArtId::ALL {
                for path in piece(set, id).paths {
                    assert!(
                        path.fill.is_some() || path.stroke.is_some(),
                        "{set:?}/{id:?} has an unpainted path"
                    );
                    assert!((0.0..=1.0).contains(&path.alpha) && path.alpha > 0.0);
                    assert!(
                        matches!(path.ops().next(), Some(Op::Move(..))),
                        "{set:?}/{id:?} does not start with a move"
                    );
                }
            }
        }
    }

    #[test]
    fn fine_lines_stay_print_safe_at_nominal_scale() {
        for set in SETS {
            for id in ArtId::ALL {
                let piece = piece(set, id);
                let min = min_stroke_pt(piece, piece.nominal_scale);
                assert!(
                    min >= 0.29,
                    "{set:?}/{id:?} has a {min:.2} pt line at nominal scale"
                );
            }
        }
    }

    #[test]
    fn ink_set_is_strictly_monochrome() {
        for id in ArtId::ALL {
            for path in piece(ArtSet::Ink, id).paths {
                let colours = path.fill.into_iter().chain(path.stroke.map(|s| s.rgb));
                for c in colours {
                    assert!(
                        c[0] == c[1] && c[1] == c[2],
                        "{id:?} uses a non-grey colour {c:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn ink_set_is_richer_than_colour_for_the_ornaments() {
        for id in [
            ArtId::Corner,
            ArtId::FrameLetter,
            ArtId::SigilStr,
            ArtId::SigilWis,
            ArtId::Divider,
        ] {
            let count = |set| {
                piece(set, id)
                    .paths
                    .iter()
                    .map(ArtPath::packed_len)
                    .sum::<usize>()
            };
            assert!(
                count(ArtSet::Ink) > count(ArtSet::Colour),
                "{id:?} ink is not richer"
            );
        }
    }

    #[test]
    fn path_counts_and_size_are_stable() {
        // Golden numbers: update deliberately when the art changes.
        let counts: Vec<(usize, usize)> = SETS
            .iter()
            .map(|&s| {
                let all = ArtId::ALL.iter().map(|&id| piece(s, id));
                (
                    all.clone().map(|p| p.paths.len()).sum(),
                    all.flat_map(|p| p.paths).map(ArtPath::packed_len).sum(),
                )
            })
            .collect();
        assert_eq!(
            counts, GOLDEN_COUNTS,
            "regenerate and review, then update GOLDEN_COUNTS"
        );
        assert!(
            counts[0].1 * 4 < 60_000 && counts[1].1 * 4 < 120_000,
            "table size budget exceeded"
        );
    }

    #[test]
    fn svg_output_is_well_formed() {
        let svg = to_svg(piece(ArtSet::Colour, ArtId::SigilStr));
        assert!(svg.starts_with("<svg") && svg.ends_with("</svg>") && !svg.contains("NaN"));
    }
}
